import random
import string
from typing import List

# Generator for valid/interesting color specification strings for gib_imlib_parse_color
# We cover common forms likely supported by Imlib-style parsers:
# - Hex: #RGB, #RGBA, #RRGGBB, #RRGGBBAA, with and without alpha
# - 0xRRGGBB, 0xAARRGGBB
# - rgb(r,g,b), rgba(r,g,b,a) with ints 0-255 and floats 0-1 for alpha
# - hsl(h,s%,l%), hsla(h,s%,l%,a)
# - Named colors (common CSS/X11 color names)
# - Variants with whitespace, tabs, leading/trailing spaces, mixed case
# - Edge extremes: 0/255, min/max hue, odd hex lengths where valid (#RGB/#RGBA)
# The function returns bytes suitable for FUZZ_PARAM_STR input

NAMED_COLORS = [
    # A mix of common X11/CSS color names
    "black", "white", "red", "green", "blue", "cyan", "magenta", "yellow",
    "gray", "grey", "darkgray", "lightgray", "darkgrey", "lightgrey",
    "orange", "purple", "brown", "pink", "violet", "indigo",
    "aliceblue", "antiquewhite", "aqua", "aquamarine", "azure",
    "beige", "bisque", "blanchedalmond", "blueviolet", "burlywood",
    "cadetblue", "chartreuse", "chocolate", "coral", "cornflowerblue",
    "cornsilk", "crimson", "darkblue", "darkcyan", "darkgoldenrod",
    "darkgreen", "darkkhaki", "darkmagenta", "darkolivegreen",
    "darkorange", "darkorchid", "darkred", "darksalmon", "darkseagreen",
    "darkslateblue", "darkslategray", "darkslategrey", "darkturquoise",
    "darkviolet", "deeppink", "deepskyblue", "dimgray", "dimgrey",
    "dodgerblue", "firebrick", "floralwhite", "forestgreen",
    "fuchsia", "gainsboro", "ghostwhite", "gold", "goldenrod",
    "greenyellow", "honeydew", "hotpink", "indianred", "ivory",
    "khaki", "lavender", "lavenderblush", "lawngreen", "lemonchiffon",
    "lightblue", "lightcoral", "lightcyan", "lightgoldenrodyellow",
    "lightgreen", "lightpink", "lightsalmon", "lightseagreen",
    "lightskyblue", "lightslategray", "lightslategrey", "lightsteelblue",
    "lightyellow", "lime", "limegreen", "linen", "maroon",
    "mediumaquamarine", "mediumblue", "mediumorchid", "mediumpurple",
    "mediumseagreen", "mediumslateblue", "mediumspringgreen",
    "mediumturquoise", "mediumvioletred", "midnightblue", "mintcream",
    "mistyrose", "moccasin", "navajowhite", "navy", "oldlace",
    "olive", "olivedrab", "orangeRed", "orchid", "palegoldenrod",
    "palegreen", "paleturquoise", "palevioletred", "papayawhip",
    "peachpuff", "peru", "plum", "powderblue", "rosybrown",
    "royalblue", "saddlebrown", "salmon", "sandybrown", "seagreen",
    "seashell", "sienna", "silver", "skyblue", "slateblue",
    "slategray", "slategrey", "snow", "springgreen", "steelblue",
    "tan", "teal", "thistle", "tomato", "turquoise", "wheat",
    "whitesmoke", "yellowgreen"
]

HEX_DIGITS = "0123456789abcdef"

def _rand_hex(n: int, rnd: random.Random) -> str:
    return ''.join(rnd.choice(HEX_DIGITS) for _ in range(n))

def _maybe_spaces(s: str, rnd: random.Random) -> str:
    # Randomly add leading/trailing spaces or tabs
    pads = ["", " ", "\t", "  ", "\t "]
    return rnd.choice(pads) + s + rnd.choice(pads)

def _hex_color(rnd: random.Random) -> str:
    form = rnd.choice([3, 4, 6, 8])
    if form == 3:
        s = "#" + _rand_hex(3, rnd)
    elif form == 4:
        s = "#" + _rand_hex(4, rnd)
    elif form == 6:
        # Bias towards extreme values sometimes
        if rnd.random() < 0.3:
            choices = ["000000", "FFFFFF", "ff0000", "00ff00", "0000ff", "ffff00", "00ffff", "ff00ff"]
            s = "#" + rnd.choice(choices)
        else:
            s = "#" + _rand_hex(6, rnd)
    else:  # 8
        if rnd.random() < 0.3:
            choices = ["000000ff", "ffffffff", "ff000080", "00000000", "ffffffff"]
            s = "#" + rnd.choice(choices)
        else:
            s = "#" + _rand_hex(8, rnd)
    # Randomly change case
    if rnd.random() < 0.5:
        s = s.upper()
    return _maybe_spaces(s, rnd)

def _hex_0x_color(rnd: random.Random) -> str:
    # 0xRRGGBB or 0xAARRGGBB
    if rnd.random() < 0.5:
        hexd = _rand_hex(6, rnd)
    else:
        hexd = _rand_hex(8, rnd)
    s = "0x" + (hexd.upper() if rnd.random() < 0.5 else hexd)
    return _maybe_spaces(s, rnd)

def _rgb_func(rnd: random.Random) -> str:
    # rgb(r,g,b) or rgba(r,g,b,a) with variability: spaces, percentages, alpha float
    def chan() -> str:
        # sometimes percent, sometimes 0-255
        if rnd.random() < 0.3:
            return f"{rnd.randint(0,100)}%"
        else:
            # bias extremes
            if rnd.random() < 0.3:
                return str(rnd.choice([0, 255]))
            return str(rnd.randint(0,255))
    def alpha() -> str:
        if rnd.random() < 0.5:
            # float 0..1
            # bias to 0, 0.5, 1
            choices = [0.0, 1.0, 0.5, rnd.random()]
            return ("{:.3f}".format(rnd.choice(choices))).rstrip('0').rstrip('.') if rnd.random() < 0.7 else str(rnd.choice([0,1]))
        else:
            # 0-255
            return str(rnd.randint(0,255))
    name = rnd.choice(["rgb", "RGB", "rgba", "RGBA"]) if rnd.random() < 0.5 else rnd.choice(["rgb", "rgba"])
    use_alpha = name.lower() == "rgba" or rnd.random() < 0.4
    comma = ","
    space = " " if rnd.random() < 0.8 else ""
    inside = f"{chan()}{comma}{space}{chan()}{comma}{space}{chan()}"
    if use_alpha:
        inside = inside + f"{comma}{space}{alpha()}"
        name = "rgba"
    else:
        name = "rgb"
    s = f"{name}({inside})"
    return _maybe_spaces(s, rnd)

def _hsl_func(rnd: random.Random) -> str:
    # hsl(h,s%,l%) or hsla(h,s%,l%,a)
    h = rnd.randint(0, 360)
    s = rnd.randint(0, 100)
    l = rnd.randint(0, 100)
    space = " " if rnd.random() < 0.8 else ""
    comma = ","
    use_alpha = rnd.random() < 0.6
    if use_alpha:
        a = rnd.choice([0.0, 1.0, 0.5, round(rnd.random(), 3)])
        a_str = ("{:.3f}".format(a)).rstrip('0').rstrip('.')
        sstr = f"hsla({h}{comma}{space}{s}%{comma}{space}{l}%{comma}{space}{a_str})"
    else:
        sstr = f"hsl({h}{comma}{space}{s}%{comma}{space}{l}%)"
    return _maybe_spaces(sstr, rnd)

def _named_color(rnd: random.Random) -> str:
    name = rnd.choice(NAMED_COLORS)
    # Random case variation
    mode = rnd.random()
    if mode < 0.33:
        name = name.upper()
    elif mode < 0.66:
        name = name.capitalize()
    # Sometimes embed extra internal spaces not allowed? Avoid to keep validity.
    return _maybe_spaces(name, rnd)

def _with_comments_or_prefix(s: str, rnd: random.Random) -> str:
    # Sometimes prefix with "color=" or append inline comment-like text which many parsers ignore
    # Keep it minimal to remain likely valid: only optional color= prefix
    if rnd.random() < 0.15:
        s = ("color=" if rnd.random() < 0.7 else "Colour=") + s
    return s

def _generate_color_string(rnd: random.Random) -> str:
    kind = rnd.choices(
        population=["hex", "hex0x", "rgb", "hsl", "name"],
        weights=[35, 10, 25, 10, 20],
        k=1
    )[0]
    if kind == "hex":
        s = _hex_color(rnd)
    elif kind == "hex0x":
        s = _hex_0x_color(rnd)
    elif kind == "rgb":
        s = _rgb_func(rnd)
    elif kind == "hsl":
        s = _hsl_func(rnd)
    else:
        s = _named_color(rnd)
    s = _with_comments_or_prefix(s, rnd)
    # Ensure total length cap
    if len(s) > 4096:
        s = s[:4096]
    return s


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    # Create 1 to N alternative color specs concatenated with newlines to let a fuzzer try multiple runs if it splits lines.
    # But the fuzzer stub passes a single string; still, a parser might handle first token. Keep single item by default.
    s = _generate_color_string(rnd)
    return s.encode("utf-8", errors="ignore")

import random
import string
from typing import List

# This generator produces interesting, valid POSIX shell-command text inputs
# for functions like shell_escape(char*). We aim to cover a wide range of
# shell metacharacters, quoting styles, expansions, and edge cases while
# keeping inputs valid C strings and <= 512 bytes as per stub behavior.

MAX_OUT = 4096
TARGET_MAX = 512  # the fuzzer stub truncates to 512, so keep inputs near/below this

# Character pools
ASCII_PRINTABLE = ''.join(chr(i) for i in range(32, 127))
SPACES = " \t\n\r\v\f"
BASIC_ALNUM = string.ascii_letters + string.digits
SHELL_META = "|&;()<>$`\\\"' *?[#~=%:+!{}@^,\n\t\r"  # include whitespace and many metacharacters
GLOB_CHARS = "*?[]!"  # globbing characters
REDIR_CHARS = ">><<|&"  # redirection and pipes
QUOTE_CHARS = "'\"`"
VAR_CHARS = "$"  # variable expansion starters

# Building blocks for shell-y snippets

def rand_choice(rng: random.Random, seq: List[str]):
    return rng.choice(seq)

def rand_word(rng: random.Random, minlen=1, maxlen=12):
    length = rng.randint(minlen, maxlen)
    alphabet = BASIC_ALNUM + "_-:."
    return ''.join(rng.choice(alphabet) for _ in range(length))

def rand_path(rng: random.Random):
    parts = []
    # choose absolute or relative
    if rng.random() < 0.5:
        parts.append('/')
    depth = rng.randint(1, 4)
    for _ in range(depth):
        # include dot-segments and spaces sometimes
        if rng.random() < 0.15:
            seg = rand_choice(rng, ['.', '..'])
        else:
            seg = rand_word(rng, 1, 10)
            if rng.random() < 0.2:
                seg += ' ' + rand_word(rng, 1, 5)
        parts.append(seg)
    # join while keeping possible leading '/'
    if parts and parts[0] == '/':
        return '/' + '/'.join(parts[1:])
    return '/'.join(parts)

def quoted_single(rng: random.Random, content: str):
    # In single quotes, only way to include a single quote is to close, escape, reopen: 'foo'\''bar'
    if "'" not in content:
        return "'" + content + "'"
    out = []
    for chunk in content.split("'"):
        out.append("'" + chunk + "'")
        out.append("\\'")
    if out:
        out.pop()  # remove trailing escape if split ended
    return ''.join(out)

def quoted_double(rng: random.Random, content: str):
    # Double quotes allow \" \$ \` escapes
    content = content.replace('"', '\\"').replace('$', '\\$').replace('`', '\\`')
    return '"' + content + '"'

def backticks(rng: random.Random, content: str):
    content = content.replace('`', '\\`')
    return '`' + content + '`'

def rand_var(rng: random.Random):
    name = rng.choice(['HOME','PATH','USER','SHELL','PWD','OLDPWD','LANG','DISPLAY'])
    style = rng.random()
    if style < 0.5:
        return f"${name}"
    else:
        return f"${{{name}}}"

def rand_arith_expansion(rng: random.Random):
    a = rng.randint(-10, 10)
    b = rng.randint(-10, 10)
    op = rng.choice(['+','-','*','/','%'])
    return f"$(({a}{op}{b}))"

def rand_command_subst(rng: random.Random):
    cmd = rng.choice(['date', 'whoami', 'echo ' + rand_word(rng), 'uname -a', 'printf %s foo'])
    if rng.random() < 0.5:
        return "$(" + cmd + ")"
    else:
        return backticks(rng, cmd)

def rand_redirection(rng: random.Random):
    # Build a variety of redirections; include a possible here-doc
    if rng.random() < 0.2:
        marker = rand_word(rng, 3, 8)
        return f"<<EOF\n{marker}\nEOF"
    op = rng.choice(['>', '>>', '2>', '2>>', '<'])
    target = rand_path(rng)
    return f"{op} {target}"

def rand_glob(rng: random.Random):
    pat = ''
    for _ in range(rng.randint(2,5)):
        c = rng.random()
        if c < 0.4:
            pat += '*'
        elif c < 0.6:
            pat += '?' 
        elif c < 0.8:
            # simple character class
            a = rng.choice(string.ascii_lowercase)
            b = rng.choice(string.ascii_lowercase)
            if a > b:
                a,b = b,a
            pat += f"[{a}-{b}]"
        else:
            pat += rng.choice(BASIC_ALNUM)
    return pat

def rand_pipe_segment(rng: random.Random):
    base = rng.choice([
        'echo', 'cat', 'grep', 'sed', 'awk', 'cut', 'tr', 'sort', 'head', 'tail', 'wc'
    ])
    args = []
    for _ in range(rng.randint(0,3)):
        choice = rng.random()
        if choice < 0.15:
            args.append(rand_var(rng))
        elif choice < 0.3:
            args.append(rand_glob(rng))
        elif choice < 0.45:
            args.append(quoted_double(rng, rand_word(rng,1,8) + ' ' + rand_word(rng,1,6)))
        elif choice < 0.6:
            args.append(quoted_single(rng, rand_word(rng,3,10)))
        elif choice < 0.75:
            args.append(rand_path(rng))
        elif choice < 0.9:
            args.append(rand_arith_expansion(rng))
        else:
            args.append(rand_command_subst(rng))
    return ' '.join([base] + args)

def rand_pipeline(rng: random.Random):
    segs = [rand_pipe_segment(rng) for _ in range(rng.randint(2,4))]
    connector = rng.choice([' | ', ' || ', ' && '])
    return connector.join(segs)

def rand_assignment(rng: random.Random):
    name = rand_word(rng, 3, 8)
    # ensure valid shell var name starts with letter or underscore
    if not (name[0].isalpha() or name[0] == '_'):
        name = '_' + name
    val = rng.choice([
        rand_word(rng,1,10),
        quoted_single(rng, rand_word(rng,3,8) + ' ' + rand_word(rng,2,6)),
        quoted_double(rng, rand_word(rng,2,6) + '=' + rand_word(rng,2,6)),
        rand_path(rng)
    ])
    return f"{name}={val}"

def rand_case_weird(rng: random.Random):
    # include tricky characters that need escaping
    samples = [
        "; rm -rf ~/tmp",  # semicolon
        "$(echo nested) && echo done",  # subshell &&
        "`echo legacy` | tr a-z A-Z",  # backticks
        "file name with spaces.txt",  # spaces
        "cmd arg\\ with\\ backslashes",  # backslashes
        "$(printf '%s' \"$HOME\")",  # quotes and var (escaped to keep valid Python string)
        "* ? [a-z] {1..3}",  # glob and brace expansion
        "| & > < >> 2>&1",  # redirections
    ]
    return rng.choice(samples)

def assemble_shell_line(rng: random.Random, budget: int):
    parts = []
    builders = [
        rand_pipeline,
        rand_assignment,
        rand_command_subst,
        rand_redirection,
        rand_glob,
        rand_case_weird,
        lambda r: quoted_single(r, ''.join(r.choice(ASCII_PRINTABLE) for _ in range(r.randint(3,12)))),
        lambda r: quoted_double(r, ''.join(r.choice(ASCII_PRINTABLE) for _ in range(r.randint(3,12)))),
    ]
    # Start with a command
    parts.append(rand_pipe_segment(rng))
    # Add random extra segments separated by spaces or newlines
    while True:
        if len(' '.join(parts)) >= budget:
            break
        sep = '\n' if rng.random() < 0.3 else ' '
        nxt = rand_choice(rng, builders)(rng)
        parts.append(sep + nxt)
        if rng.random() < 0.2:
            # sometimes finish early
            break
    s = ' '.join(parts)
    # Clamp to budget
    if len(s) > budget:
        s = s[:budget]
    return s

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Compose a shell-like script line with diverse features likely to exercise escaping
    base = assemble_shell_line(rng, rng.randint(64, TARGET_MAX))

    # Optionally prepend environment and append trailing constructs to vary structure
    extras = []
    if rng.random() < 0.5:
        extras.append(rand_assignment(rng))
    if rng.random() < 0.4:
        extras.append('export ' + rand_assignment(rng))
    if rng.random() < 0.3:
        extras.append('cd ' + rand_path(rng))
    pre = ' && '.join(extras)
    if pre:
        full = pre + ' && ' + base
    else:
        full = base

    # Sometimes wrap everything in grouping or subshells to introduce parentheses
    wrap = rng.random()
    if wrap < 0.2:
        full = '( ' + full + ' )'
    elif wrap < 0.4:
        full = '$( ' + full + ' )'

    # Ensure non-empty and within bounds
    if not full:
        full = rand_word(rng)
    if len(full) > TARGET_MAX:
        full = full[:TARGET_MAX]

    # Return as bytes (valid C-string bytes, no NULs included)
    data = full.encode('utf-8', errors='ignore')
    if len(data) > MAX_OUT:
        data = data[:MAX_OUT]
    return data
